    // flagNameMixedDamage: debug/log/tooling name for bit i of MixedDamage —
    // out-of-range bits name as "???"
    public static String flagNameMixedDamage(int bit) {
        switch (bit) {
            case 0:
                return "Bleeding";
            case 1:
                return "Burning";
            case 2:
                return "Stunned";
            case 3:
                return "Slowed";
            case 4:
                return "Poisoned";
            case 5:
                return "Shielded";
            case 6:
                return "Airborne";
            case 7:
                return "Downed";
            default:
                return "???";
        }
    }

    // flagNamesMixedDamage renders the set bits of value as "A|B" — "0" for the
    // empty set, bits past the declared variants as hex
    public static String flagNamesMixedDamage(long value) {
        StringBuilder names = new StringBuilder();
        if ((value & (1L << 0)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Bleeding");
        }
        if ((value & (1L << 1)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Burning");
        }
        if ((value & (1L << 2)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Stunned");
        }
        if ((value & (1L << 3)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Slowed");
        }
        if ((value & (1L << 4)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Poisoned");
        }
        if ((value & (1L << 5)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Shielded");
        }
        if ((value & (1L << 6)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Airborne");
        }
        if ((value & (1L << 7)) != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            names.append("Downed");
        }
        if (value >>> 8 != 0) {
            if (names.length() > 0) {
                names.append('|');
            }
            // Long.toHexString renders the bit pattern, not a sign
            names.append("0x").append(Long.toHexString((value >>> 8) << 8));
        }
        return names.length() == 0 ? "0" : names.toString();
    }

